import sys
p=sys.argv[1]; s=open(p).read()
def rep(a,b):
    global s
    assert s.count(a)==1, "НЕТ: "+a[:70]; s=s.replace(a,b)
# коды: нули впереди, порядок
rep("Тройка «сладкий, солёный, горький», то есть $\\{1,3,5\\}$, станет словом 101010, тройка «кислый, солёный, острый», то есть $\\{2,3,4\\}$, — словом 011100. Каждой тройке отвечает слово длины 6 ровно с тремя единицами, и такие слова легко перебирать по порядку, как в словаре: 111000, 110100, 110010, 110001, 101100 и так далее.",
    "Тройка «сладкий, солёный, горький», то есть $\\{1,3,5\\}$, станет словом 101010, тройка «кислый, солёный, острый», то есть $\\{2,3,4\\}$, — словом 011100. Это не числа, а записи из шести знаков, и нули впереди важны: 011100 говорит, что первый вкус не выбран. Каждой тройке отвечает слово длины 6 ровно с тремя единицами, и такие слова легко перебирать по порядку — по убыванию, если читать их как числа: 111000, 110100, 110010, 110001, 101100 и так далее.")
# словарь, стулья, вывод
rep("Эта таблица работает как словарь: каждому набору отвечает ровно одно слово, и каждое слово с двумя единицами — перевод ровно одного набора. Набор восстанавливается по слову: это номера мест, где стоят единицы. Соответствие с таким свойством называют взаимно однозначным (по-учёному — биекцией). Если между двумя совокупностями есть взаимно однозначное соответствие, предметов в них поровну. Так учитель, не пересчитывая детей, видит, что их столько же, сколько стульев: каждый сидит на своём стуле, и свободных стульев нет. Дальше в тексте этим приёмом мы будем пользоваться постоянно.",
    "Эта таблица работает как словарь в обе стороны: каждому набору отвечает ровно одно слово, и каждое слово с двумя единицами — перевод ровно одного набора. Набор восстанавливается по слову: это номера мест, где стоят единицы. Соответствие, которое работает в обе стороны, называют взаимно однозначным (по-учёному — биекцией). Если между двумя совокупностями есть взаимно однозначное соответствие, предметов в них поровну. Так учитель, не пересчитывая детей, видит, что их столько же, сколько стульев: каждый сидит на своём стуле, никто не сидит вдвоём, и свободных стульев нет. Поэтому тройки вкусов можно не выписывать, а считать слова: их столько же. Дальше в тексте этим приёмом мы будем пользоваться постоянно.")
# мостик к определению
rep("Теперь можно сказать то же самое точно.","Теперь можно сказать то же самое точно. Набор предметов, взятых из данных, математики называют подмножеством, а сами предметы — элементами.")
# пары: перестройка
a=s.index("Сколько пар можно выбрать из $n$ предметов?"); b=s.index("{{S:c4}}")+len("{{S:c4}}")
new_pairs='''Сколько пар можно выбрать из $n$ предметов? Из таблицы: из трёх предметов три пары, из четырёх — шесть. Найдём ответ для любого $n$. Разберём три способа; в каждом сначала посчитаем пары из пяти предметов — должно получиться 10, — а потом то же самое в общем виде.

*Способ 1 — по наименьшему элементу.* Пара $\\{i,j\\}$ с $i\\lt j$ задаётся меньшим числом $i$ и бо́льшим $j$. Если меньшее число равно $i$, бо́льшее можно выбрать $n-i$ способами: это любое из чисел $i+1,\\dots,n$. Для пяти предметов: при $i=1$ четыре пары, при $i=2$ три, при $i=3$ две, при $i=4$ одна, всего $4+3+2+1=10$. В общем случае
$$\\binom n2=(n-1)+(n-2)+\\dots+2+1.$$
Чтобы сосчитать такую сумму, запишем её в обратном порядке под исходной и сложим столбиками. Для пяти предметов:
$$\\begin{array}{ccccccc}4&+&3&+&2&+&1\\\\1&+&2&+&3&+&4\\end{array}$$
Каждый столбик даёт 5, столбиков 4, поэтому удвоенная сумма равна $5\\cdot4=20$, а сама сумма — 10. В общем случае каждый столбик даёт $n$, столбиков $n-1$, удвоенная сумма равна $n(n-1)$, и пар $\\frac{n(n-1)}2$.

*Способ 2 — лесенка и шоколадка.* Нарисуем таблицу $n\\times n$ и закрасим клетки строго выше диагонали: клетка в строке $i$ и столбце $j$ отвечает паре $\\{i,j\\}$ с $i\\lt j$. Закрашенные клетки образуют лесенку. Если считать её клетки по строкам, получится $(n-1)+(n-2)+\\dots+1$, если по столбцам — $1+2+\\dots+(n-1)$: одно и то же множество клеток, посчитанное двумя способами.

Отразим лесенку относительно диагонали — получится вторая лесенка, под диагональю. Её клетка в строке $j$ и столбце $i$ отвечает упорядоченной паре $(j,i)$, а клетка верхней лесенки — паре $(i,j)$. Пары $(2,5)$ и $(5,2)$ разные, а множество $\\{2,5\\}$ одно. Вместе две лесенки занимают все клетки, кроме диагональных; таких упорядоченных пар $n(n-1)$: первое число выбирается $n$ способами, второе — $n-1$. Сдвинем нижнюю лесенку на клетку вверх, и две лесенки сложатся в прямоугольник из $n-1$ ряда по $n$ клеток — шоколадку. Каждое множество $\\{i,j\\}$ посчитано в ней дважды, поэтому пар вдвое меньше: $\\frac{n(n-1)}2$. Для пяти предметов шоколадка $4\\times5$ состоит из 20 клеток, а пар 10.

{{S:c5}}

*Способ 3 — многоугольник.* Возьмём выпуклый $n$-угольник. Его стороны и диагонали — это все пары вершин. Из каждой вершины выходит $n-1$ отрезок, и сумма по вершинам, $n(n-1)$, считает каждый отрезок дважды, с обоих концов; значит, отрезков $\\frac{n(n-1)}2$. У пятиугольника из каждой вершины выходит 4 отрезка, всего $\\frac{5\\cdot4}2=10$: пять сторон и пять диагоналей. Это тот же подсчёт, что в задаче о рукопожатиях: если каждый из $n$ человек пожал руку каждому, рукопожатий $\\frac{n(n-1)}2$.

{{S:c4}}'''
s=s[:a]+new_pairs+s[b:]
rep("Все пять способов привели к одному ответу.","Все три способа привели к одному ответу.")
rep("При $n=0$ и $n=1$ обе части равны нулю: пар нет. Доказательство — любой из способов 1–5.","При $n=0$ и $n=1$ обе части равны нулю: пар нет. Доказательство — любой из способов 1–3.")
rep("Оба приёма ещё вернутся.","Оба приёма ещё вернутся.\n\nСо сложением задом наперёд связан анекдот: учитель задал классу сложить числа от 1 до 100, а маленький Гаусс сразу написал ответ, 5050. Это именно анекдот. В первой биографии Гаусса, вышедшей в 1856 году, история о школьной задаче есть, но чисел от 1 до 100 в ней нет; по данным Брайана Хейса, собравшего больше сотни пересказов, эти числа появляются только в книге 1938 года.")
rep("как с лесенкой по строкам и по столбцам.","как с лесенкой по строкам и по столбцам или с отрезками по вершинам.")
# пустой выбор
rep("Ничего не выбрать — значит выбрать пустое подмножество, в котором нет ни одного элемента. Множества считаются равными, если у них одни и те же элементы, поэтому пустое подмножество одно: у двух пустых множеств элементы одни и те же — никаких. На языке слов это ещё проще: слово длины $n$ без единиц одно, 0000.",
    "Почему способ один, а не ноль? Ничего не выбрать — тоже вариант выбора; в вопросе из вступления его специально исключили словами «хотя бы один вкус». На языке слов это видно сразу: слово 0000 — настоящее слово, его можно написать, и оно одно. На языке множеств ничего не выбрать — значит взять пустое подмножество, в котором нет ни одного элемента. Множества считаются равными, если у них одни и те же элементы, поэтому пустое подмножество одно: у двух пустых множеств элементы одни и те же — никаких.")
# симметрия формулировки
rep("превращаются друг в друга, если поменять в каждом слове нули на единицы: 1000 становится 0111.","превращаются друг в друга, если заменить каждый ноль единицей, а каждую единицу — нулём: 1000 становится 0111.")
rep("*Доказательство — поменять цифры.* Заменим в слове (утверждение 2) каждую цифру противоположной.","*Доказательство — поменять цифры.* Заменим в слове (утверждение 2) каждый ноль единицей, а каждую единицу — нулём.")
# строки с нуля
rep("Ряд для четырёх предметов — это строка номер 4.","Строки нумеруются с нуля, и ряд для четырёх предметов — это строка номер 4.")
# второе равенство
rep("Из второго равенства, поделив на $k+1$, получаем соотношение между соседними числами строки.","Из равенства $(n-k)\\binom nk=(k+1)\\binom n{k+1}$, поделив на $k+1$, получаем соотношение между соседними числами строки.")
rep("Пройдём так по шестой строке от края: $\\binom61=\\frac61\\cdot1=6$,","Пройдём так по шестой строке от края. При $n=6$ множитель $\\frac{n-k}{k+1}$ равен $\\frac61$ при $k=0$, $\\frac52$ при $k=1$ и $\\frac43$ при $k=2$: $\\binom61=\\frac61\\cdot1=6$,")
rep("способами — проверьте по формуле.","способами — это утверждение 8 при $n=25$ и $k=10$; проверьте по формуле.")
rep("Это одно из первых явных доказательств по индукции.","Так устроено доказательство по индукции: проверить первый случай и показать, что из каждого случая следует следующий. Это одно из первых явных таких доказательств.")
# неразрывный пробел перед тире вне формул
out=[]
for line in s.split("\n"):
    if not line.startswith("$$") and not line.startswith("|") and not line.startswith("{{"):
        parts=line.split("$")
        for i in range(0,len(parts),2): parts[i]=parts[i].replace(" — "," — ")
        line="$".join(parts)
    out.append(line)
s="\n".join(out)
open(p,"w").write(s)
print("ok")
